import sys, time, threading

def cuenta(n):
    # trabajo puro de CPU: suma de cuadrados
    total = 0
    for i in range(n):
        total += i * i
    return total

def correr(hilos, trabajo_total):
    por_hilo = trabajo_total // hilos
    lista = [threading.Thread(target=cuenta, args=(por_hilo,)) for _ in range(hilos)]
    t0 = time.perf_counter()
    for h in lista: h.start()
    for h in lista: h.join()
    return time.perf_counter() - t0

gil = sys._is_gil_enabled() if hasattr(sys, "_is_gil_enabled") else True
print(f"Python {sys.version.split()[0]} · GIL activo: {gil}")
TOTAL = 40_000_000
for hilos in (1, 2, 4):
    t = min(correr(hilos, TOTAL) for _ in range(5))
    print(f"{hilos} hilo(s): {t:.2f} s")
